content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --secondary-color: #f3f4f6;
  --secondary-hover: #e5e7eb;
  --text-color: #1f2937;
  --text-light: #6b7280;
  --bg-color: #f9fafb;
  --card-bg: #ffffff;
  --border-color: #e5e7eb;
  --success-color: #10b981;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.header {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.header h1 {
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--primary-color);
}

.header p {
  color: var(--text-light);
  font-size: 0.95rem;
}

.progress-bar {
  width: 100%;
  height: 8px;
  background-color: var(--border-color);
  border-radius: 4px;
  overflow: hidden;
  margin-top: 5px;
}

.progress-fill {
  height: 100%;
  background-color: var(--success-color);
  transition: width 0.3s ease;
}

.stats {
  display: flex;
  justify-content: space-between;
  font-size: 0.9rem;
  color: var(--text-light);
  background: var(--card-bg);
  padding: 10px 16px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.card-container {
  perspective: 1000px;
  width: 100%;
  height: 320px;
  cursor: pointer;
}

.flashcard {
  width: 100%;
  height: 100%;
  position: relative;
  transform-style: preserve-3d;
  transition: transform 0.6s cubic-bezier(0.4, 0.2, 0.2, 1);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.flashcard.flipped {
  transform: rotateY(180deg);
}

.flashcard-inner {
  position: absolute;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 30px;
  background-color: var(--card-bg);
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  text-align: center;
}

.flashcard-front {
  z-index: 2;
}

.flashcard-back {
  transform: rotateY(180deg);
  z-index: 1;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  align-items: center;
}

.btn {
  padding: 10px 20px;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-secondary {
  background-color: var(--secondary-color);
  color: var(--text-color);
}

.btn-secondary:hover {
  background-color: var(--secondary-hover);
}

.word-list {
  background: var(--card-bg);
  padding: 16px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  max-height: 250px;
  overflow-y: auto;
}

.word-list h3 {
  font-size: 1.1rem;
  margin-bottom: 10px;
  color: var(--text-color);
}

.word-list ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.word-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  background-color: var(--bg-color);
  border-radius: 8px;
  font-size: 0.95rem;
}

.word-list li.mastered {
  border-left: 4px solid var(--success-color);
}

.word-list li.learning {
  border-left: 4px solid var(--primary-color);
}

export interface WordItem {
  id: string;
  english: string;
  japanese: string;
  pronunciation: string;
  example: string;
  status: 'learning' | 'mastered';
}

import { WordItem } from '../types';

interface CardProps {
  card: WordItem;
  isFlipped: boolean;
  onFlip: () => void;
}

export default function Card({ card, isFlipped, onFlip }: CardProps) {
  return (
    <div className="card-container" onClick={onFlip}>
      <div className={`flashcard ${isFlipped ? 'flipped' : ''}`}>
        <div className="flashcard-inner flashcard-front">
          <h2>{card.english}</h2>
          <p style={{ color: 'var(--text-light)', marginTop: '8px' }}>[{card.pronunciation}]</p>
          <p style={{ marginTop: '16px', fontSize: '0.85rem', color: 'var(--text-light)' }}>（クリックして意味を確認）</p>
        </div>
        <div className="flashcard-inner flashcard-back">
          <h3>{card.japanese}</h3>
          <p style={{ marginTop: '16px', fontStyle: 'italic', color: 'var(--text-light)' }}>"{card.example}"</p>
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { WordItem } from './types';
import Card from './components/Card';
import './index.css';

const initialWords: WordItem[] = [
  { id: '1', english: 'apple', japanese: 'りんご', pronunciation: 'ˈæp.əl', example: 'I eat an apple every day.', status: 'learning' },
  { id: '2', english: 'book', japanese: '本', pronunciation: 'bʊk', example: 'She is reading an interesting book.', status: 'learning' },
  { id: '3', english: 'cat', japanese: '猫', pronunciation: 'kæt', example: 'The cat is sleeping on the sofa.', status: 'learning' },
  { id: '4', english: 'dog', japanese: '犬', pronunciation: 'dɔːɡ', example: 'My dog likes to run in the park.', status: 'learning' },
  { id: '5', english: 'elephant', japanese: '象', pronunciation: 'ˈel.ɪ.fənt', example: 'The elephant has a very long trunk.', status: 'learning' },
  { id: '6', english: 'flower', japanese: '花', pronunciation: 'ˈflaʊ.ər', example: 'She picked a beautiful flower.', status: 'learning' },
  { id: '7', english: 'guitar', japanese: 'ギター', pronunciation: 'ɡɪˈtɑːr', example: 'He plays the guitar in a band.', status: 'learning' },
  { id: '8', english: 'house', japanese: '家', pronunciation: 'haʊs', example: 'They live in a large white house.', status: 'learning' },
  { id: '9', english: 'island', japanese: '島', pronunciation: 'ˈaɪ.lənd', example: 'We visited a tropical island last summer.', status: 'learning' },
  { id: '10', english: 'juice', japanese: 'ジュース', pronunciation: 'dʒuːs', example: 'Would you like some orange juice?', status: 'learning' },
];

export default function App() {
  const [cards, setCards] = useState<WordItem[]>(initialWords);
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [isFlipped, setIsFlipped] = useState<boolean>(false);

  const currentCard = cards[currentIndex] || cards[0];

  const handleFlip = () => {
    setIsFlipped(!isFlipped);
  };

  const handleNext = () => {
    setIsFlipped(false);
    setCurrentIndex((prev) => (prev + 1) % cards.length);
  };

  const handlePrev = () => {
    setIsFlipped(false);
    setCurrentIndex((prev) => (prev - 1 + cards.length) % cards.length);
  };

  const handleStatusChange = (status: 'learning' | 'mastered') => {
    const updated = cards.map((card, idx) => {
      if (idx === currentIndex) {
        return { ...card, status };
      }
      return card;
    });
    setCards(updated);
    handleNext();
  };

  const masteredCount = cards.filter((c) => c.status === 'mastered').length;
  const progressPercent = (masteredCount / cards.length) * 100;

  return (
    <div className="app-container">
      <header className="header">
        <h1>英単語暗記カード</h1>
        <p>カードをクリックして意味を確認しよう！</p>
        <div className="progress-bar">
          <div className="progress-fill" style={{ width: `${progressPercent}%` }}></div>
        </div>
      </header>

      <div className="stats">
        <span>カード: {currentIndex + 1} / {cards.length}</span>
        <span>習得済み: {masteredCount} / {cards.length}</span>
      </div>

      <Card card={currentCard} isFlipped={isFlipped} onFlip={handleFlip} />

      <div className="controls">
        <button className="btn btn-secondary" onClick={handlePrev}>前へ</button>
        <button 
          className="btn btn-primary" 
          onClick={() => handleStatusChange(currentCard.status === 'mastered' ? 'learning' : 'mastered')}
        >
          {currentCard.status === 'mastered' ? '未習得に戻す' : '知っている！'}
        </button>
        <button className="btn btn-secondary" onClick={handleNext}>次へ</button>
      </div>

      <div className="word-list">
        <h3>単語一覧</h3>
        <ul>
          {cards.map((card, idx) => (
            <li 
              key={card.id} 
              className={card.status} 
              style={{ cursor: 'pointer' }} 
              onClick={() => { setCurrentIndex(idx); setIsFlipped(false); }}
            >
              <span><strong>{card.english}</strong> : {card.japanese}</span>
              <span style={{ fontSize: '0.8rem', color: card.status === 'mastered' ? 'var(--success-color)' : 'var(--text-light)' }}>
                {card.status === 'mastered' ? '習得済み' : '学習中'}
              </span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}
